import numpy as np
rng=np.random.default_rng(0)
def rot_z(a):
    c,s=np.cos(a),np.sin(a); return np.array([[c,-s,0],[s,c,0],[0,0,1]])
def align(d):
    d=np.array(d,float); d/=np.linalg.norm(d); z=np.array([0,0,1.])
    v=np.cross(z,d); c=np.dot(z,d)
    if np.linalg.norm(v)<1e-8: return np.eye(3) if c>0 else np.diag([1,-1,-1.])
    vx=np.array([[0,-v[2],v[1]],[v[2],0,-v[0]],[-v[1],v[0],0]])
    return np.eye(3)+vx+vx@vx/(1+c)

dmf=[('O',(0,0,2.10)),('C',(0.96,0,2.92)),('H',(0.72,0,3.99)),
     ('N',(2.26,0,2.59)),('C',(3.29,0,3.62)),('C',(2.64,0,1.18))]
alk=[('C',(0,0,2.10)),('C',(1.30,0,2.86)),('C',(-1.15,0,2.77)),
     ('H',(-2.10,0,2.23)),('C',(-1.15,0,4.27))]
cl=[('Cl',(0,0,2.33))]

def add_h3(cpos,parent,bl=1.09,phase=0.0):
    a=cpos-parent; a/=np.linalg.norm(a)
    t=np.array([1.,0,0])
    if abs(np.dot(t,a))>0.9: t=np.array([0,1.,0])
    p1=np.cross(a,t); p1/=np.linalg.norm(p1); p2=np.cross(a,p1)
    th=np.radians(180-109.5); out=[]
    for k in range(3):
        ph=2*np.pi*k/3+phase
        out.append(cpos+bl*(np.cos(th)*a+np.sin(th)*(np.cos(ph)*p1+np.sin(ph)*p2)))
    return out

dirs=[('cl',[0,0,1]),('dmf',[0,0,-1]),('dmf',[1,0,0]),('dmf',[-1,0,0]),
      ('cl',[0,1,0]),('alk',[0,-1,0])]
tm={'cl':cl,'dmf':dmf,'alk':alk}

def build(spins):
    groups=[]
    for (name,d),sp in zip(dirs,spins):
        R=align(d)@rot_z(np.radians(sp))
        t=tm[name]
        ats=[(e,R@np.array(p,float)) for e,p in t]
        if name=='dmf':
            Np=ats[3][1]
            for j in (4,5):
                for h in add_h3(ats[j][1],Np): ats.append(('H',h))
        if name=='alk':
            for j,pj in ((1,0),(4,2)):
                for h in add_h3(ats[j][1],ats[pj][1]): ats.append(('H',h))
        groups.append(ats)
    return groups

def score(groups):
    s=0.0
    for a in range(len(groups)):
        for b in range(a+1,len(groups)):
            A=np.array([p for e,p in groups[a]]); B=np.array([p for e,p in groups[b]])
            D=np.linalg.norm(A[:,None,:]-B[None,:,:],axis=2)
            s+=np.sum(np.clip(3.3-D,0,None)**2)
    return s

best=None
for it in range(40000):
    sp=rng.uniform(0,360,6)
    sp[0]=0; sp[4]=0
    g=build(sp); v=score(g)
    if best is None or v<best[0]: best=(v,sp)
print(best)
g=build(best[1])
atoms=[('Cr',np.zeros(3))]
for grp in g: atoms+=grp
with open('start2.xyz','w') as f:
    f.write(f"{len(atoms)}\nCr(2-buten-2-yl)Cl2(dmf)3 S=3/2\n")
    for e,p in atoms: f.write(f"{e} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
